def pusht_image_to_chw_float01(image: np.ndarray) -> np.ndarray:
    """Convert Push-T HWC image data to CHW float32 in [0, 1]."""
    image = np.asarray(image, dtype=np.float32)
    if image.ndim != 3 or image.shape[-1] != 3:
        raise ValueError(f"Expected HWC RGB image, got shape {image.shape}")
    if image.max(initial=0.0) > 1.0:
        image = image / 255.0
    return np.moveaxis(image, -1, 0).astype(np.float32)

def pusht_image_sequence_to_tchw_float01(images: np.ndarray) -> np.ndarray:
    """Convert Push-T THWC image sequence to TCHW float32 in [0, 1]."""
    images = np.asarray(images, dtype=np.float32)
    if images.ndim != 4 or images.shape[-1] != 3:
        raise ValueError(f"Expected THWC RGB image sequence, got shape {images.shape}")
    if images.max(initial=0.0) > 1.0:
        images = images / 255.0
    return np.moveaxis(images, -1, 1).astype(np.float32)

def _validate_square_crop_tchw(images: np.ndarray, crop_size: Optional[int]) -> Optional[int]:
    if crop_size is None:
        return None
    crop_size = int(crop_size)
    if crop_size <= 0:
        raise ValueError(f"crop_size must be positive, got {crop_size}")
    if images.ndim != 4:
        raise ValueError(f"Expected TCHW image sequence, got shape {images.shape}")
    height, width = images.shape[-2], images.shape[-1]
    if crop_size > height or crop_size > width:
        raise ValueError(
            f"crop_size={crop_size} exceeds image size {(height, width)}"

def apply_hue_tchw_float01(images: np.ndarray, theta: float) -> np.ndarray:
    """Apply a hue rotation to a TCHW float01 sequence, one angle for all frames."""
    if theta == 0.0:
        return images
    m = _hue_matrix(float(theta))
    out = np.einsum("ij,tjhw->tihw", m, images)
    return np.ascontiguousarray(np.clip(out, 0.0, 1.0), dtype=np.float32)

def center_crop_tchw_float01(images: np.ndarray, crop_size: Optional[int]) -> np.ndarray:
    """Center-crop a TCHW float image sequence, preserving the time stack."""
    crop_size = _validate_square_crop_tchw(images, crop_size)
    if crop_size is None:
        return images
    height, width = images.shape[-2], images.shape[-1]
    top = (height - crop_size) // 2
    left = (width - crop_size) // 2
    cropped = images[..., top:top + crop_size, left:left + crop_size]
    return np.ascontiguousarray(cropped, dtype=np.float32)

